module spi_controller (
    input wire clk,
    input wire reset,
    input wire cs,
    input wire mosi,
    output reg miso
);
    reg [7:0] data_reg;
    reg [2:0] bit_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_reg <= 8'b0;
            bit_count <= 3'b0;
            miso <= 1'b0;
        end else if (!cs) begin
            // Capture data on MOSI on the rising edge of the clock
            data_reg <= {data_reg[6:0], mosi};
            if (bit_count == 3'd7) begin
                bit_count <= 3'b0; // Reset bit count after 8 bits
            end else begin
                bit_count <= bit_count + 1; // Increment bit count
            end
        end 
    end

    always @(negedge clk or posedge reset) begin
        if (reset) begin
            miso <= 1'b0;
        end else if (!cs && bit_count > 0) begin
            // Transmit data on MISO on the falling edge of the clock
            miso <= data_reg[7];
            data_reg <= {data_reg[6:0], 1'b0}; // Shift left
        end
    end
endmodule

