module fir_filter (
    input wire clk,
    input wire rst,
    input wire [15:0] x_in,
    output reg [15:0] y_out
);
    reg [15:0] coeffs [0:15]; // 16 coefficients
    reg [15:0] x_reg [0:15];  // Shift register for input samples
    integer i;

    initial begin
        // Predefined coefficients for the FIR filter
        coeffs[0] = 16'h0001;
        coeffs[1] = 16'h0002;
        coeffs[2] = 16'h0003;
        coeffs[3] = 16'h0004;
        coeffs[4] = 16'h0005;
        coeffs[5] = 16'h0006;
        coeffs[6] = 16'h0007;
        coeffs[7] = 16'h0008;
        coeffs[8] = 16'h0009;
        coeffs[9] = 16'h000A;
        coeffs[10] = 16'h000B;
        coeffs[11] = 16'h000C;
        coeffs[12] = 16'h000D;
        coeffs[13] = 16'h000E;
        coeffs[14] = 16'h000F;
        coeffs[15] = 16'h0010;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset output and shift registers
            y_out <= 16'b0;
            for (i = 0; i < 16; i = i + 1) begin
                x_reg[i] <= 16'b0;
            end
        end else begin
            // Shift the input samples
            for (i = 15; i > 0; i = i - 1) begin
                x_reg[i] <= x_reg[i - 1];
            end
            x_reg[0] <= x_in;

            // Compute the output using the FIR filter equation
            y_out <= 16'b0;
            for (i = 0; i < 16; i = i + 1) begin
                y_out <= y_out + (x_reg[i] * coeffs[i]);
            end
        end
    end
endmodule

