module dma_controller (
    input wire clk,
    input wire reset,
    input wire start,
    input wire [7:0] src_addr,
    input wire [7:0] dst_addr,
    input wire [15:0] data,
    output reg done,
    output reg [15:0] mem
);
    reg [7:0] current_src;
    reg [7:0] current_dst;

    always @(posedge clk or posedge reset) begin
