module spi_master (
    input wire clk,
    input wire reset,
    input wire start,
    input wire [7:0] data_in,
    input wire MISO,
    output reg [7:0] MOSI,
    output reg SPI_CLK,
    output reg SPI_EN
);
    reg [3:0] bit_count;
    reg [7:0] shift_reg;
    reg state;

    localparam IDLE = 1'b0;
    localparam TRANSMIT = 1'b1;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            MOSI <= 8'b0;
            SPI_CLK <= 1'b0;
            SPI_EN <= 1'b0;
            bit_count <= 4'd0;
        end else begin
            case (state)
                IDLE: begin
                    SPI_EN <= 1'b0;
                    if (start) begin
                        SPI_EN <= 1'b1;
                        shift_reg <= data_in;
                        bit_count <= 4'd0;
                        state <= TRANSMIT;
                    end
                end
                TRANSMIT: begin
                    if (bit_count < 4'd8) begin
                        MOSI <= shift_reg[7]; // Send MSB first
                        shift_reg <= {shift_reg[6:0], 1'b0}; // Shift left
                        SPI_CLK <= ~SPI_CLK; // Toggle clock
                        bit_count <= bit_count + 1;
                    end else begin
                        SPI_EN <= 1'b0; // Transmission completed
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

