module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire start_tx,
    input wire [7:0] data_in,
    output reg tx,
    output reg ready
);
    reg [3:0] state;
    reg [3:0] bit_index;
    reg [9:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit
    parameter IDLE = 0, START = 1, DATA = 2, STOP = 3;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            tx <= 1;
            ready <= 1;
            bit_index <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start_tx && ready) begin
                        shift_reg <= {1'b1, data_in, 1'b0}; // Add stop bit and start bit
                        state <= START;
                        ready <= 0;
                        bit_index <= 0;
                    end
                end
                START: begin
                    tx <= 0; // Transmit start bit
                    state <= DATA;
                end
                DATA: begin
                    if (bit_index < 8) begin
                        tx <= shift_reg[bit_index]; // Transmit data bits
                        bit_index <= bit_index + 1;
                    end else begin
                        state <= STOP;
                    end
                end
                STOP: begin
                    tx <= 1; // Transmit stop bit
                    state <= IDLE;
                    ready <= 1; // Ready for next transmission
                end
            endcase
        end
    end
endmodule

