module fractional_n_pll(  
    input clk_ref,  
    input [3:0] freq_div,  
    output reg clk_out  
);  
    reg [3:0] counter;  
    reg clk_div;  
    initial begin  
        counter = 0;  
        clk_out = 0;  
    end  

    always @(posedge clk_ref) begin  
        counter <= counter + 1;  
        if (counter >= freq_div) begin  
            counter <= 0;  
            clk_div <= ~clk_div;  
        end  
    end  

    always @(posedge clk_div) begin  
        clk_out <= ~clk_out;  
    end  
endmodule

