module dma_controller(input clk, input rst, input start_ch1, input start_ch2, output reg done_ch1, output reg done_ch2);  
    reg [1:0] state;  
    reg [1:0] next_state;  
    reg ch1_active, ch2_active;  

    parameter IDLE = 2'b00, CH1_TRANSFER = 2'b01, CH2_TRANSFER = 2'b10;  

    // State transition  
    always @(posedge clk or posedge rst) begin  
        if (rst)  
            state <= IDLE;  
        else  
            state <= next_state;  
    end  

    // Next state logic  
    always @(*) begin  
        case (state)  
            IDLE: begin  
                if (start_ch1) begin  
                    next_state = CH1_TRANSFER;  
                end else if (start_ch2) begin  
                    next_state = CH2_TRANSFER;  
                end else begin  
                    next_state = IDLE;  
                end  
            end  
            CH1_TRANSFER: begin  
                next_state = IDLE; // Transfer complete after one clock cycle  
            end  
            CH2_TRANSFER: begin  
                next_state = IDLE; // Transfer complete after one clock cycle  
            end  
            default: next_state = IDLE;  
        endcase  
    end  

    // Output logic  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            done_ch1 <= 0;  
            done_ch2 <= 0;  
        end else begin  
            case (state)  
                CH1_TRANSFER: begin  
                    done_ch1 <= 1;  
                    done_ch2 <= 0;  
                end  
                CH2_TRANSFER: begin  
                    done_ch1 <= 0;  
                    done_ch2 <= 1;  
                end  
                IDLE: begin  
                    done_ch1 <= 0;  
                    done_ch2 <= 0;  
                end  
            endcase  
        end  
    end  
endmodule

