module pwm_generator(
    input clk,
    input [3:0] duty_cycle,
    output reg pwm_out
);
    reg [3:0] counter;

    always @(posedge clk) begin
        if (counter < duty_cycle)
            pwm_out <= 1;
        else
            pwm_out <= 0;

        counter <= (counter == 4'd15) ? 4'd0 : counter + 4'd1;
    end
endmodule

