module i2c_controller(
    input clk,
    input rst,
    input [7:0] data_in,
    input start,
    output reg SDA,
    output reg SCL,
    output reg tx_done
);

    reg [3:0] state;
    reg [3:0] bit_cnt;
    localparam IDLE = 4'b0000,
               START = 4'b0001,
               SEND = 4'b0010,
               STOP = 4'b0011;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            SDA <= 1;
            SCL <= 1;
            tx_done <= 0;
            bit_cnt <= 0;
        end else begin
            case (state)
                IDLE: begin
                    SDA <= 1;
                    SCL <= 1;
                    tx_done <= 0;
                    if (start) begin
                        state <= START;
                    end
                end
                START: begin
                    SDA <= 0; // Start condition
                    SCL <= 1;
                    state <= SEND;
                    bit_cnt <= 0;
                end
                SEND: begin
                    if (bit_cnt < 8) begin
                        SDA <= data_in[7 - bit_cnt]; // Send data bit
                        SCL <= 0; // Clock low
                        #1 SCL <= 1; // Clock high
                        bit_cnt <= bit_cnt + 1;
                    end else begin
                        state <= STOP; // Go to stop
                    end
                end
                STOP: begin
                    SDA <= 0; // Prepare for stop condition
                    SCL <= 0; // Clock low
                    #1 SCL <= 1; // Clock high
                    SDA <= 1; // Stop condition
                    tx_done <= 1; // Transmission complete
                    state <= IDLE; // Return to idle
                end
            endcase
        end
    end
endmodule

