module floyd_warshall #(parameter N = 4, parameter INF = 16'hFFFF) (  
    input wire [N*N*16-1:0] graph,  
    output reg [N*N*16-1:0] dist  
);  
    integer i, j, k;  
    reg [15:0] temp_dist [0:N-1][0:N-1];  

    always @* begin  
        // Initialize the distance matrix from the input graph  
        for (i = 0; i < N; i = i + 1) begin  
            for (j = 0; j < N; j = j + 1) begin  
                if (i == j)  
                    temp_dist[i][j] = 16'h0000;  
                else  
                    temp_dist[i][j] = (graph[(i*N+j)*16 +: 16] == INF) ? INF : graph[(i*N+j)*16 +: 16];  
            end  
        end  

        // Floyd-Warshall algorithm  
        for (k = 0; k < N; k = k + 1) begin  
            for (i = 0; i < N; i = i + 1) begin  
                for (j = 0; j < N; j = j + 1) begin  
                    if (temp_dist[i][k] + temp_dist[k][j] < temp_dist[i][j])  
                        temp_dist[i][j] = temp_dist[i][k] + temp_dist[k][j];  
                end  
            end  
        end  

        // Output the resulting distance matrix  
        for (i = 0; i < N; i = i + 1) begin  
            for (j = 0; j < N; j = j + 1) begin  
                dist[(i*N+j)*16 +: 16] = temp_dist[i][j];  
            end  
        end  
    end  
endmodule

