module watchdog_timer(
    input wire clk,
    input wire rst,
    input wire enable,
    output reg timeout
);
    parameter TIMEOUT_VALUE = 8'd100; // Timeout value in clock cycles
    reg [7:0] counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 8'd0;
            timeout <= 1'b0;
        end else if (enable) begin
            if (counter < TIMEOUT_VALUE) begin
                counter <= counter + 1'b1;
                timeout <= 1'b0;
            end else begin
                timeout <= 1'b1; // Timeout reached
            end
        end else begin
            counter <= 8'd0; // Reset counter if enable is low
            timeout <= 1'b0;
        end
    end
endmodule

