    wire [3:0] sorted23[0:3];
    wire [7:0] merged01, merged23;

    // Merge in0 and in1
    assign sorted01[0] = (in0 < in1) ? in0 : in1;
    assign sorted01[1] = (in0 < in1) ? in1 : in0;

