module fractional_n_pll (
    input wire clk_ref,          // Reference clock input
    input wire [7:0] div_ratio,  // Division ratio input
    input wire reset,            // Asynchronous reset
    output reg clk_out           // Output clock
);

    reg [7:0] counter;
    reg [7:0] n_counter;
    reg div_enable;

    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            counter <= 0;
            n_counter <= 0;
            clk_out <= 0;
            div_enable <= 0;
        end else begin
            if (counter < div_ratio - 1) begin
                counter <= counter + 1;
            end else begin
                counter <= 0;
                clk_out <= ~clk_out;
                div_enable <= 1;
            end

            if (div_enable) begin
                n_counter <= n_counter + 1;
                if (n_counter >= (div_ratio / 2)) begin
                    n_counter <= 0;
                    div_enable <= 0;
                end
            end
        end
    end
endmodule

