            repeat(2) @(posedge clk);


            req = 4'b1001;
            @(posedge clk);
            #1;


            #1;



            check_outputs(4'b0001, 8'h00);
        end
        endtask

    task testcase007;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Request Withdrawal", test_num);
            reset_dut();
            req = 4'b0100;
